import study as r
def write(name,text):
    p=r.HERE/name;p.parent.mkdir(parents=True,exist_ok=True)
    if p.exists():raise RuntimeError('NO_REPORT_OVERWRITE:'+name)
    p.write_text(text,encoding='utf-8')
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,row))+' |\n' for row in rows)
def main():
    import numpy as np
    import matplotlib
