    import matplotlib.pyplot as plt
    from mouse_statistics import PRIMARY
    for phase in ('science','nulls_complete','original_pg_certificate'):
        if r.load(r.HERE/f'results/{phase}/native/gate_result.json')['gate']!='PASS':raise RuntimeError('CRITICAL_GATE_STOP')
    full=r.load(r.HERE/'results/exploratory_statistics.json');stats=full['mouse_statistics']['primary']['statistics'];allrows=r.load(r.HERE/'results/science/native/scientific_scores.json')['rows'];cov=r.load(r.HERE/'results/preflight_corrected/native/coverage.json');nulls=full['null_statistics']
    fits=[r.load(p) for p in (r.HERE/'results/original_pg_certificate/native').glob('*_fit.json')];units=[u for f in fits for u in f['records']]
    numerical={'original_definition_max_PG':max(u['original_definition_PG'] for u in units),'AD_original_definition_max_PG':max(u['AD_original_definition_PG'] for u in units),'max_AD_scaled_error':max(u['AD_scaled_error'] for u in units),'max_AD_objective_error':max(u['AD_objective_error'] for u in units),'new_scientific_model_cases':910,'new_scientific_unit_fit_attempts':21476,'necessary_identical_endpoint_reconstruction_model_cases':910,'necessary_identical_endpoint_reconstruction_unit_fits':21476,'total_new_track_optimizer_unit_fit_executions':42952,'original_M3_refits':0,'original_offset_refits':0,'all_910_coefficient_hashes_identical':True,'final_access':False}
    r.save(r.HERE/'results/numerical_summary.json',numerical)
    resulttable=table(['Contribution','CA1 gain','DG gain','CA1−DG','95% mouse bootstrap CI','Raw paired p','Holm p'],[[k,f"{stats[k]['mean_CA1_gain']:.8f}",f"{stats[k]['mean_DG_gain']:.8f}",f"{stats[k]['mean_CA1_minus_DG']:.8f}",f"[{stats[k]['CI95'][0]:.8f}, {stats[k]['CI95'][1]:.8f}]",f"{stats[k]['paired_signflip_p']:.8f}",f"{stats[k]['holm_p']:.8f}"] for k in PRIMARY])
    baseline=full['fixed_ridge_baselines'];baseline_table=table(['Old representation','CA1 mean gain over stationary','DG mean gain over stationary'],[[kind,*[f"{np.mean([v['gain_over_stationary'] for v in baseline if v['region']==reg and v['model']==kind]):.8f}" for reg in ('CA1','DG')]] for kind in ('stationary','history','population','event','drift','combined')])
    null_table=table(['Control','Contrast','Observed pooled gain','Reference pooled mean','Pooled Holm p','Regional centered Holm p'],[[v['suite'],v['contrast'],f"{v['observed_pooled_gain']:.8f}",f"{v['null_pooled_mean']:.8f}",f"{v['pooled_holm_p']:.4f}",f"{v['regional_holm_p']:.4f}"] for v in nulls.values()])
    sens_names=['primary','matched16','rate_matched','boundary20','boundary40'];sens_table=table(['View','Paired mice',*PRIMARY],[[v,full['mouse_statistics'][v]['mice'],*[f"{full['mouse_statistics'][v]['statistics'][k]['mean_CA1_minus_DG']:.8f}" for k in PRIMARY]] for v in sens_names])
    shared={z['mouse_id'] for z in allrows if z['view'].startswith('shared_probe_')};lopo={z['mouse_id'] for z in allrows if z['view'].startswith('leave_probe_')}
    write('RESULTS.md','# Complete exploratory Development results\n\nNats per actual nominal curated-release unit-bin; equal weighting of 13 paired mice. Development A/B and some scores were examined before this new registration. These results are exploratory. No final evaluation.\n\n'+resulttable+'\nNo primary contrast passes Holm<=0.05. The other-unit-history raw p is below 0.05, but its corrected p is not. A percentile interval excluding zero is not a substitute for the registered multiplicity gate. Both ROIs have positive mean history/combined predictive gains; cross-ROI differences are heterogeneous and do not demonstrate reproducibility.\n\n## Reused baselines\n\n'+baseline_table+'\nAll 1,638 scores, including every ridge and seed, remain in results/reused_M3_records.json and the original immutable files. The table uses preregistered fixed ridge0.1, all-three-seed mean. Old population includes own history; old combined duplicates own history.\n\n## Fixed sensitivities\n\n'+sens_table+f'\nShared-probe-only views are available for {len(shared)}/13 mice; leave-probe-out views for {len(lopo)}/13. All per-mouse probe composition and all available views are retained, including unavailable group coverage. The probe views do not establish independent-probe replication. Sensitivity intervals are descriptive and are not selected to rescue the primary result.\n\n## All registered fixed-predictor controls\n\n'+null_table+'\nThese 999-replicate control distributions preserve fixed trial membership. Temporal totals are exactly preserved. Condition/bin/order controls are conditional stress tests with exchangeability limitations. Control-specific p values are not independent confirmation of a CA1/DG biological difference and are not original M5 refit nulls. Complete distributions and confidence ranges are retained in exploratory_statistics.json and the native null JSON files.\n\n## Numerical audit\n\n'+json.dumps(numerical,indent=2)+'\n\nThe first accepted implementation used a projected-step norm. A prospective supplemental certificate rebuilt identical endpoints and applied the unchanged original outward-gradient PG oracle. All 910 coefficient hashes match exactly; both executions remain counted. No original M3 or offset fit was repeated. Initial no-fit preflight failures caused by the incorrect nominal trial-count assertion, and the observability replay, are preserved with corrected exact-manifest checks and a regression.\n')
    figures=r.HERE/'figures';figures.mkdir(exist_ok=False);plt.rcParams.update({'font.size':10,'figure.dpi':150,'savefig.dpi':200})
    fig,ax=plt.subplots(figsize=(8,4.8))
    for i,k in enumerate(PRIMARY):
        v=stats[k];ax.scatter(v['mouse_differences'],np.full(13,i),s=20,color='#aab3bf',alpha=.8);ax.errorbar(v['mean_CA1_minus_DG'],i,xerr=[[v['mean_CA1_minus_DG']-v['CI95'][0]],[v['CI95'][1]-v['mean_CA1_minus_DG']]],fmt='o',color='#194c77',capsize=4);ax.text(.99,i,f"Holm p={v['holm_p']:.4f}",transform=ax.get_yaxis_transform(),ha='right',va='bottom',fontsize=8)
    ax.axvline(0,color='black',lw=.8);ax.set_yticks(range(4),['Own history','Other-unit mean history','Stimulus / nominal time','Combined']);ax.set_xlabel('CA1 − DG predictive gain (nats / nominal unit-bin)');ax.set_title('13 development mice: no primary Holm-significant contrast');ax.grid(axis='x',alpha=.2);fig.tight_layout();fig.savefig(figures/'primary_mouse_effects.png');fig.savefig(figures/'primary_mouse_effects.pdf');plt.close(fig)
    fig,ax=plt.subplots(figsize=(8,4.8));kinds=['history','population','event','drift','combined']
    for j,reg in enumerate(('CA1','DG')):
        means=[];errs=[]
        for kind in kinds:
            x=np.array([z['gain_over_stationary'] for z in baseline if z['region']==reg and z['model']==kind]);random=np.random.default_rng(120214);ci=np.quantile(x[random.integers(0,13,(10000,13))].mean(axis=1),[.025,.975]);means.append(x.mean());errs.append([x.mean()-ci[0],ci[1]-x.mean()])
        ax.errorbar(np.arange(5)+(j-.5)*.12,means,yerr=np.array(errs).T,fmt='o',capsize=3,label=reg)
    ax.set_xticks(range(5),['Own history','Population*','Context','Drift','Combined*']);ax.axhline(0,color='black',lw=.8);ax.set_ylabel('Gain over stationary (nats / nominal unit-bin)');ax.set_title('Reused M3 at fixed ridge 0.1: equal-mouse means and bootstrap CIs');ax.legend();fig.text(.5,.01,'* Old population includes own history; combined repeats own-history columns.',ha='center',fontsize=8);fig.tight_layout(rect=(0,.04,1,1));fig.savefig(figures/'reused_baselines.png');fig.savefig(figures/'reused_baselines.pdf');plt.close(fig)
    fig,axes=plt.subplots(2,2,figsize=(10,7))
    for ax,k in zip(axes.ravel(),PRIMARY):
        for i,v in enumerate(sens_names):
            q=full['mouse_statistics'][v]['statistics'][k];ax.errorbar(i,q['mean_CA1_minus_DG'],yerr=[[q['mean_CA1_minus_DG']-q['CI95'][0]],[q['CI95'][1]-q['mean_CA1_minus_DG']]],fmt='o',color='#194c77',capsize=3)
        ax.axhline(0,color='black',lw=.8);ax.set_title(k);ax.set_xticks(range(5),['32 units','16 units','Rate match','Boundary20','Boundary40'],rotation=25);ax.set_ylabel('CA1 − DG gain');ax.grid(axis='y',alpha=.2)
    fig.suptitle('All fixed sensitivities: descriptive mouse bootstrap intervals');fig.tight_layout();fig.savefig(figures/'sensitivities.png');fig.savefig(figures/'sensitivities.pdf');plt.close(fig)
    fig,axes=plt.subplots(2,2,figsize=(10,7))
    for ax,k in zip(axes.ravel(),PRIMARY):
        for i,suite in enumerate(('T','S','B','O')):
            q=nulls[suite+'_'+k];mid=q['null_pooled_mean'];ci=q['null_pooled95'];ax.vlines(i,ci[0],ci[1],color='#767676');ax.scatter(i,mid,color='#767676',s=25)
        ax.axhline(nulls['T_'+k]['observed_pooled_gain'],color='#194c77',label='Observed');ax.set_xticks(range(4),['Temporal','Condition','Bin label','Order']);ax.set_title(k);ax.set_ylabel('Pooled mean predictive gain');ax.legend(fontsize=8)
    fig.suptitle('999 fixed-predictor references per suite; conditional, exploratory');fig.tight_layout();fig.savefig(figures/'falsification.png');fig.savefig(figures/'falsification.pdf');plt.close(fig)
    abstract='We asked whether CA1 and DG differ in the predictive contributions of own spike history, other-unit population history and known stimulus/time context. We preserved a frozen 26-mouse allocation and used only the 13 development mice; all development inference is exploratory because A/B data and some scores had previously been examined. We reused 1,638 baseline fits and 78 shared-offset fits, and evaluated small, causally indexed nested Poisson GLMs with fixed ridge and numerical acceptance. Both subfields showed positive mean predictive gains from own history and combined features. None of four primary CA1-minus-DG contrasts passed the registered four-test Holm correction; the smallest corrected p was 0.0693 for other-unit mean history. Whole-mouse uncertainty, fixed unit/rate/anatomy/probe sensitivities and all four 999-replicate fixed-predictor controls are reported. These results do not establish a reproducible subfield difference or a causal mechanism. Original recurrent M4 failures remain unchanged. Final evaluation is unexposed and requires separate authorization.'
    body='# Predictive Structure of Neural Population Activity Across Mouse Hippocampal Subfields\n\nExploratory Method Paper draft — P12-PREDICTIVE-STRUCTURE-V2. Draft completion is distinct from scientific validation. Authors, affiliations and submission declarations: [DECISION REQUIRED before submission].\n\n## Abstract\n\n'+abstract+'\n\n## 1. Introduction\n\nPopulation activity can be predictively structured by a unit\'s own past, the recent activity of other selected units, and known trial context. A fitted population model can improve prediction without identifying an anatomical mechanism or a causal interaction. This study asks whether these measured contributions differ between provider-labeled CA1 and DG in a frozen curated-release mouse cohort. The original P12 recurrent-model comparison stopped at numerical convergence gates. The present track instead uses small nested Poisson representations, retains the complete historical failure record, and targets a narrower observational predictive question.\n\nThe falsifiable exploratory hypotheses are four two-sided animal-level differences in conditional own-history, other-unit mean-history, stimulus/time and combined-feature gains. Nuisance-controlled contrasts are fixed before new scientific evaluation. The study contributes a transparent predictive decomposition, full mouse-level uncertainty and explicit tests against context/order and conditional temporal references. It does not claim a preferred recurrent regime, neural mechanism, independently confirmed anatomy or final validation.\n\n## 2. Methods\n\n'+(r.HERE/'METHODS.md').read_text().replace('# Frozen methods and interpretation\n\n','')+'\n\n## 3. Results\n\n'+(r.HERE/'RESULTS.md').read_text().replace('# Complete exploratory Development results\n\n','')+'\n\n### Figures\n\n![Figure 1: Mouse-level primary differences](figures/primary_mouse_effects.png)\n\nFigure 1. Individual mouse differences, equal-mouse means and whole-mouse percentile intervals. None of the four Holm-adjusted paired tests meets 0.05.\n\n![Figure 2: Reused baselines](figures/reused_baselines.png)\n\nFigure 2. All-three-seed mean scores at the registered common ridge; mouse bootstrap uncertainty. Full grids remain in A4.\n\n![Figure 3: Registered sensitivities](figures/sensitivities.png)\n\nFigure 3. Five frozen views, all with 13 eligible paired mice. No view replaces the primary test.\n\n![Figure 4: Fixed-predictor falsification](figures/falsification.png)\n\nFigure 4. Pooled reference means and 95% replicate ranges, compared with observed gain. Reference intervals are conditional null distributions, not mouse bootstrap uncertainty or independent experiments.\n\n## 4. Discussion\n\nThe tractable representations show that past counts predict nominal curated-release activity in both provider-labeled subfields. The primary regional differences are mixed or inconclusive after the registered correction. The small other-unit mean-history contrast trends toward greater DG gain, but its corrected p value does not pass the four-hypothesis gate. This result cannot be promoted by its unadjusted p value, a descriptive interval or a favorable sensitivity. The own-history and combined contrasts vary substantially across mice. Negative, mixed and inconclusive evidence is part of the result rather than a reason to select another model or threshold.\n\nPredictive dependence may reflect shared input, stimulus modulation, latent behavioral state, sampling, preprocessing and omitted interactions. Rate matching changes the selected population and does not exactly equalize rates. Boundary distances are label-based channel proxies; no independent histological assignment has been obtained. Multiple units and probes do not increase the independent mouse count. Conditional temporal and label/order stress tests depend on modeling/exchangeability assumptions and do not establish causality. Curated nominal exposure and whole-session upstream sorting prevent claims of native continuity or a completely naive acquisition pipeline.\n\nThe original recurrent-model numerical failures remain a separate limitation. Gradient validity did not make those optimizers converge, and the subsequent three-policy conditioning study remained inconclusive. The present GLM success does not retrospectively clear M4, complete original M5/M6, or validate NAP/CWP. The transparent PG-oracle implementation correction and all deterministic certification replays are retained, with exact coefficient equality and original thresholds.\n\nGeneralization is restricted to an exploratory within-release development cohort. All four hypotheses, model definitions, analysis code and acceptance criteria are frozen for a later protected final-mouse assessment. Final C/D are locked in this mission. A negative or inconclusive final assessment must be retained; no final-based replacement selection is permitted. An external cohort, independent anatomical registration and causal intervention would be separate future work.\n\n## 5. Conclusion\n\nThis complete exploratory draft provides a numerically audited, narrower predictive analysis. It does not establish reproducibly different CA1/DG contributions under the registered primary multiplicity gate. Final validation remains prospective and unauthorized.\n\n## Reproducibility and declarations\n\nA1-A10 accompany the draft. Public saved-evidence reproduction regenerates mouse statistics and verifies all numerical/custody/hash records without opening neural counts or final data. Full neural reruns require the protected custodian/runtime and a fresh authorized execution registration; cached successful fits are deliberately reused. Provider data-access terms and institutional secondary-analysis declarations must be confirmed by the authors before submission; this draft does not invent an ethics approval, independent custodian or unrestricted raw-data redistribution license.\n'
    write('MANUSCRIPT.md',body)
    for name,rows2 in [('all_old_baseline_fits.csv',r.load(r.HERE/'results/reused_M3_records.json')),('fixed_ridge_baseline_scores.csv',baseline)]:
        p=r.HERE/'supplements'/name;p.parent.mkdir(parents=True,exist_ok=True)
        with p.open('x',encoding='utf-8',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows2[0]));w.writeheader();w.writerows(rows2)
    audit=['A1 — Protocol: PROTOCOL.md, protocol_registration.json; retrospective development exposure disclosed.','A2 — Manifest: exact A/B export hash, 13 mice, selected unit/trial identities and frozen 26/13/13 allocation; protected counts not public.','A3 — Pipeline: source/execution registrations, original_pg_certificate, stats source, native zero-capability proofs.','A4 — All baselines/ablations: all_old_baseline_fits.csv, scientific_scores.json, all910 histories and frozen offset reuse.','A5 — Holdout: FINAL_VALIDATION_PLAN.md; final D unexposed, C fitting not authorized here.','A6 — Statistics: exploratory_statistics.json, primary_statistics.json; equal mouse, bootstrap10000, signflip8192, Holm4; sensitivity/no favorable replacement.','A7 — Nulls: all104 suites×999 saved distributions, conditional assumptions and no original M5 claim.','A8 — QC/leakage: original source/QC receipts and immutable masks; fresh native role tests; original-PG certification; preflight test failures retained.','A9 — Limits/failed analyses: METHODS.md, RESULTS.md, original M4 and conditioning inconclusive commits, anatomical/probe/rate/continuity restrictions.','A10 — Reproduction: reproduce.ps1; saved scores/oracles/hashes, zero new fits, no neural/final reads. Full protected reruns are not claimed by this command.']
    write('A1_A10_CLAIM_AUDIT.md','# A1–A10 and claim audit\n\n'+'\n\n'.join(audit)+'\n\n| Claim | Evidence | Allowed status |\n|---|---|---|\n| Complete exploratory draft | MANUSCRIPT, figures, supplements, all registered development outputs | Draft complete; final validation pending |\n| Reproducible CA1/DG difference | Four Holm tests, smallest0.0693359375 | NOT ESTABLISHED |\n| Development predictive gains | Full B scores, mouse tables, registered controls | Exploratory observational prediction |\n| New GLM numerical validity | Every strict original-PG/AD certificate, exact endpoint hashes | New track only |\n| Original M4 recovery | Immutable FAIL/INCONCLUSIVE evidence | NOT RECOVERED |\n| Anatomy confirmed / causal mechanism | Provider proxies, observational data | NOT ESTABLISHED |\n| Final evaluation | Custody receipts final flags false | NOT RUN / LOCKED |\n')
    details=[
        (r.HERE/'PROTOCOL.md').read_text()+'\n\nRegistration:\n\n```json\n'+json.dumps(r.load(r.HERE/'protocol_registration.json'),indent=2)+'\n```\n',
        'Exact development metadata manifest: [development_manifest.json](../results/development_manifest.json). Neural counts are protected, not redistributed. Each file digest binds the original matched trial masks and selected unit IDs. Allocation remains26=13development+13final, no replacement.\n\n'+table(['Session','Mouse','A trials','B trials','CA1 units','DG units'],[[z['session_id'],z['mouse_id'],len(z['trial_ids']['A']),len(z['trial_ids']['B']),len(z['unit_ids']['CA1']),len(z['unit_ids']['DG'])] for z in r.load(r.HERE/'results/development_manifest.json')['sessions']]),
        'Pipeline order: protocol/atomic baseline→exact historical reuse and coverage→synthetic oracles→registered GLM fits→strict original-PG identical-endpoint certificate→fixed-predictor nulls→mouse statistics→draft/final freeze. See all execution registrations and code files. AppContainer capability count0; role probes and cleanup recorded for every phase. Original and corrected preflight attempts remain.\n\n'+(r.HERE/'IMPLEMENTATION_ERRATA.md').read_text(),
        baseline_table+'\n'+resulttable+'\nFull1,638 original rows: all_old_baseline_fits.csv. All new model/view scores: ../results/science/native/scientific_scores.json. All910 histories and identical strict certificates are in the two native results directories. No successful old M3/offset refit.\n',
        (r.HERE/'FINAL_VALIDATION_PLAN.md').read_text(),
        resulttable+'\n'+sens_table+'\nFull raw paired differences, bootstrap intervals, exact8192 sign-flip assignments, Holm p values and all leave-one-mouse-out means: ../results/exploratory_statistics.json. The four primary family is not reduced after outcomes. Sensitivities do not replace primary results. Mouse is independent; nominal bin count is a scoring denominator only.\n',
        null_table+'\nAll104 complete999-replicate reference distributions: ../results/nulls_complete/native. All26×999 temporal-total invariants checked, zero null fits. Temporal reference is conditional on nuisance model and observed trial counts; label/order exchangeability is assumed, not proved. These are not original M5 refit nulls and not exact causal tests. Both complete16-test corrected families are retained.\n',
        (r.HERE/'IMPLEMENTATION_ERRATA.md').read_text()+'\n\nSource/QC preservation: ../preservation_manifest.json and original paper12_resume1/results/M2 gates/receipts. Original per-condition24/16, units>=5, quarantined probe, finite CCF and A-only physiological QC persist. Final count access flags false. Strict numerical summary:\n\n```json\n'+json.dumps(numerical,indent=2)+'\n```\n',
        'No primary corrected hypothesis passes0.05; absence of significance does not establish equivalence. Development exposure, conditional nulls, incomplete independent anatomy/probe replication, residual rate mismatch, limited selected-unit population representation, upstream whole-session processing and nominal exposure restrict claims. Final validation remains unrun. Original M4failures and three optimizer-policy failures are immutable. No preferred regime/NAP/CWP/causal claim.\n\n'+(r.HERE/'METHODS.md').read_text(),
        'From repository root run:\n\n```powershell\npowershell -NoProfile -ExecutionPolicy Bypass -File .\\paper12_predictive_v2\\reproduce.ps1\n```\n\nThis validates43 regression/oracle checks, all sealed evidence, preserved historical bytes and exact regenerated mouse/null statistics from public scalar results. It performs zero real fits and opens no neural/final counts. Python, NumPy and SciPy versions are recorded in ../analysis_environment.json. Original native runtime file hashes are in the execution registrations. Full protected numerical reruns require custodian access and fresh execution registration, and are not claimed by the saved command. Failed attempts, all fits and necessary PG reconstruction cost remain counted.\n'
    ]
    for i,(text,detail) in enumerate(zip(audit,details),1):write(f'supplements/A{i:02d}.md',f'# {text}\n\n'+detail+'\nAll claims are bounded by ../METHODS.md, ../A1_A10_CLAIM_AUDIT.md and ../FINAL_VALIDATION_PLAN.md.\n')
    import scipy
    r.save(r.HERE/'analysis_environment.json',{'python':sys.version,'platform':platform.platform(),'numpy':np.__version__,'scipy':scipy.__version__,'matplotlib':matplotlib.__version__,'role':'public-scalar analysis/artifact rendering only','final_access':False})
    print('EXPLORATORY_DRAFT_BUILT',numerical)
